# -*- coding: utf-8 -*-
from __future__ import annotations
import ast, base64, hashlib, json, re, shutil, sys
from datetime import datetime
from pathlib import Path

ROOT = Path(r"C:\stockdata\stock_server_test")
BACKUP_ROOT = Path(r"C:\stockdata\backups")
REPORT_ROOT = ROOT / "data-test"

EXPECTED_OLD_SHA256 = {'config.py': '14f16f8a7a9a6084b17f4a5d594ad9e870052e32a0ff9aa05e5685707fc1c3a7', '.env.example': 'd7c2509c2db080b8f3c95bb107aada4d8e2de832f777ec1fb517bb7a7bd2657f', 'services\\rate_limit_service.py': 'eadee410d3e76f4de8fdd2f0416e0a7a367607985de8eaac88f2a7e72b664d30', 'services\\market_query_security.py': 'de09583cf1ed5b84f928e9167045cdb6df6d9d123ffc619e4450f2e9cb1fa143', 'routes\\market_data_routes.py': '32caf2615d8dd994374274b5a9f42919712414ebecf1f538bb3d281db9a60adb', 'tests\\test_market_query_security.py': '78d6fc7b173d0908d8f275451b4f37376b0e8b9a928896f6a02ec91e456c3688', 'tests\\test_market_response_limits.py': 'ebbe17be499e84f701dbd354419a1ecf394055c5b6d117f0f34fea6b6b393542', 'tests\\test_rate_limit_service.py': '0cce9b114f7128be8ff7c3d48f543522b2ea719c33ba95fb9fd008700f829e01'}
EXPECTED_PLAN_SHA256 = '11e0dba6887834eba2f7eb71931c1cfd44a8d4565abe365919c2f16de927b07a'
NEW_CONTENT_B64 = {'config.py': '', '.env.example': '', 'services\\rate_limit_service.py': '', 'services\\market_query_security.py': '', 'routes\\market_data_routes.py': '', 'tests\\test_market_query_security.py': '', 'tests\\test_market_response_limits.py': '', 'tests\\test_rate_limit_service.py': ''}

TOUCH_REL = [
    "config.py",
    ".env.example",
    ".env",
    r"services\rate_limit_service.py",
    r"services\market_query_security.py",
    r"routes\market_data_routes.py",
    r"tests\test_rate_limit_service.py",
    r"tests\test_market_query_security.py",
    r"tests\test_market_response_limits.py",
]


def fail(message: str) -> None:
    raise RuntimeError(message)

def read(path: Path) -> str:
    return path.read_text(encoding="utf-8")

def write(path: Path, text: str) -> None:
    path.write_text(text, encoding="utf-8", newline="\n")

def sha_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

def update_env_key(text: str, key: str, value: str, *, insert_after: str | None = None) -> str:
    pattern = re.compile(rf"^{re.escape(key)}=.*$", re.M)
    line = f"{key}={value}"
    if pattern.search(text):
        return pattern.sub(line, text, count=1)
    if insert_after:
        anchor = re.search(rf"^{re.escape(insert_after)}=.*$", text, re.M)
        if not anchor:
            fail(f"Cannot add {key}: anchor {insert_after} not found")
        return text[:anchor.end()] + "\n\n" + line + text[anchor.end():]
    return text.rstrip() + "\n\n" + line + "\n"

def backup_files(stamp: str) -> Path:
    backup_dir = BACKUP_ROOT / f"risk-policy-round2b-{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=False)
    for rel in TOUCH_REL:
        source = ROOT / rel
        if not source.exists():
            fail(f"Required file missing: {source}")
        dest = backup_dir / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, dest)
    return backup_dir

def restore_files(backup_dir: Path) -> None:
    for rel in TOUCH_REL:
        backup = backup_dir / rel
        target = ROOT / rel
        if backup.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(backup, target)

def main() -> int:
    if Path.cwd().resolve() != ROOT.resolve():
        fail(f"Run from {ROOT}; current={Path.cwd()}")
    if not (ROOT / ".venv" / "Scripts" / "python.exe").exists():
        fail("TEST virtualenv not found")

    env_path = ROOT / ".env"
    env_text = read(env_path)
    required_env = [
        "DEPLOYMENT_SLOT=test",
        "REDIS_KEY_PREFIX=stock_server_test",
        "MIN_REQUESTS_PER_MINUTE=1",
        "MARKET_QUERY_MAX_CONCURRENT_GLOBAL=16",
        "MARKET_QUERY_GENERAL_MAX_CONCURRENT_PER_USER=2",
        "MARKET_QUERY_GENERAL_MAX_CONCURRENT_PER_TOKEN=2",
        "MARKET_QUERY_SPECIAL_MAX_CONCURRENT_PER_USER=4",
        "MARKET_QUERY_SPECIAL_MAX_CONCURRENT_PER_TOKEN=4",
    ]
    missing = [item for item in required_env if item not in env_text]
    if missing:
        fail("Round2A/TEST guard failed: " + ", ".join(missing))
    if not (
        r"DB_FILE=C:\stockdata\stock_server_test\data\stock_server.db" in env_text
        or "DB_FILE=data/stock_server.db" in env_text
        or r"DB_FILE=data\stock_server.db" in env_text
    ):
        fail("TEST guard failed: DB_FILE is not stock_server_test")

    # Verify the exported snapshot still matches the on-disk source.
    for rel, expected in EXPECTED_OLD_SHA256.items():
        actual_path = ROOT / rel
        if not actual_path.exists():
            fail(f"Snapshot file missing: {actual_path}")
        actual = sha_text(read(actual_path))
        if actual != expected:
            fail(
                f"Source changed since Round2B snapshot: {rel}; "
                "stop and re-export current source before patching"
            )

    plan_path = ROOT / r"services\plan_catalog.py"
    if sha_text(read(plan_path)) != EXPECTED_PLAN_SHA256:
        fail("plan_catalog.py changed since Round2B snapshot; stop and re-export")

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup_dir = backup_files(stamp)
    changed = []
    try:
        for rel, encoded in NEW_CONTENT_B64.items():
            target = ROOT / rel
            new_text = base64.b64decode(encoded).decode("utf-8")
            write(target, new_text)
            changed.append(rel)

        # Real .env: only non-secret policy keys; never print the file.
        env_text = read(env_path)
        env_text = update_env_key(env_text, "MIN_REQUESTS_PER_MINUTE", "1")
        env_text = update_env_key(
            env_text,
            "MARKET_QUERY_CONCURRENCY_RETRY_AFTER_SECONDS",
            "2",
            insert_after="MARKET_QUERY_LEASE_TTL_SECONDS",
        )
        write(env_path, env_text)
        changed.append(".env")

        # Syntax gate.
        for rel in NEW_CONTENT_B64:
            if rel.endswith(".py"):
                path = ROOT / rel
                ast.parse(read(path), filename=str(path))

        # Static invariants.
        security = read(ROOT / r"services\market_query_security.py")
        routes = read(ROOT / r"routes\market_data_routes.py")
        config = read(ROOT / "config.py")
        checks = {
            "plan_aware_concurrency": "def concurrency_limits_for_plan(" in security,
            "general_2_2": "MARKET_QUERY_GENERAL_MAX_CONCURRENT_PER_USER" in security,
            "special_4_4": "MARKET_QUERY_SPECIAL_MAX_CONCURRENT_PER_TOKEN" in security,
            "retry_after": 'response.headers["Retry-After"]' in routes,
            "plan_passed_to_lease": 'int(user.get("api_key_id") or 0),\n            plan,' in routes,
            "serialization_inside_lease": "with request_lease(" in routes and "return jsonify({" in routes,
            "min_default_one": 'MIN_REQUESTS_PER_MINUTE", 1, 1, 100000' in config,
            "retry_config": "MARKET_QUERY_CONCURRENCY_RETRY_AFTER_SECONDS" in config,
        }
        failed = [name for name, ok in checks.items() if not ok]
        if failed:
            fail("Post-patch invariant failure: " + ", ".join(failed))

    except Exception:
        restore_files(backup_dir)
        raise

    REPORT_ROOT.mkdir(parents=True, exist_ok=True)
    report = {
        "round": "2B",
        "root": str(ROOT),
        "backup_dir": str(backup_dir),
        "changed_files": changed,
        "production_modified": False,
        "service_restarted": False,
        "policy": {
            "general": {"rpm": 120, "user_concurrency": 2, "token_concurrency": 2},
            "special": {"rpm": 300, "user_concurrency": 4, "token_concurrency": 4},
            "admin_concurrency": "legacy per-user/per-token fallback",
            "global_market_query_concurrency": 16,
            "retry_after_seconds": 2,
            "active_http_hard_limit": None,
            "default_response_rows": 5000,
            "bulk_response_rows": 10000,
            "lease_covers_dataframe_records_jsonify": True,
        },
    }
    report_path = REPORT_ROOT / f"risk-policy-round2b-{stamp}.json"
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")

    print("ROUND2B_PATCH=PASS")
    print(f"BACKUP_DIR={backup_dir}")
    print("CHANGED_FILES=" + ",".join(changed))
    print(f"REPORT={report_path}")
    print("PRODUCTION_MODIFIED=FALSE")
    print("SERVICE_RESTARTED=FALSE")
    print("NEXT=run Round 2B verification and targeted pytest; do not publish yet")
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"ROUND2B_PATCH=FAIL: {type(exc).__name__}: {exc}", file=sys.stderr)
        raise
